    try:
        plugin_load_context.plugin_resolved_path = pull_cache[name]
        plugin_load_context.plugin_resolved_name = name
        plugin_load_context.resolved = True
        return plugin_load_context
    except KeyError:
        # Cache miss.  Now let's find the plugin
        pass

